package com.civicshield.api;
import com.civicshield.api.ApiModels.*;import com.civicshield.domain.*;import com.civicshield.repo.*;import com.civicshield.risk.CascadeRiskEngine;import com.civicshield.security.JwtService;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1") public class ApiController {
 private final UserRepository users;private final IncidentRepository incidents;private final RiskRepository risks;private final AlertRepository alerts;private final RecommendationRepository recommendations;private final SimulationRepository simulations;private final AuditRepository audit;private final PasswordEncoder encoder;private final JwtService jwt;private final CascadeRiskEngine engine=new CascadeRiskEngine();private final ObjectMapper json;
 public ApiController(UserRepository u,IncidentRepository i,RiskRepository r,AlertRepository a,RecommendationRepository rec,SimulationRepository s,AuditRepository au,PasswordEncoder e,JwtService j,ObjectMapper om){users=u;incidents=i;risks=r;alerts=a;recommendations=rec;simulations=s;audit=au;encoder=e;jwt=j;json=om;}
 private AppUser actor(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new IllegalStateException("Authenticated user no longer exists"));}
 private Incident incident(long id){return incidents.findById(id).orElseThrow(()->new IllegalArgumentException("Incident not found: "+id));}
 private Map<String,Double> parse(String s){try{return json.readValue(s,new TypeReference<>(){});}catch(Exception e){throw new IllegalStateException("Stored analysis is invalid");}}
 private Map<String,Object> parseObject(String s){try{return json.readValue(s,new TypeReference<>(){});}catch(Exception e){throw new IllegalStateException("Stored simulation inputs are invalid");}}
 private Map<String,Double> parseFactors(Object value){
  if(!(value instanceof Map<?,?> values))throw new IllegalStateException("Stored simulation localFactors are invalid");
  Map<String,Double> factors=new LinkedHashMap<>();
  for(var entry:values.entrySet()){
   if(!(entry.getKey() instanceof String key)||!(entry.getValue() instanceof Number number))throw new IllegalStateException("Stored simulation localFactors are invalid");
   factors.put(key,number.doubleValue());
  }
  return factors;
 }
 private String stringify(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException("Could not encode data");}}
 private IncidentView view(Incident i){return new IncidentView(i.getId(),i.getTitle(),i.getType(),i.getLocation(),i.getDescription(),i.getSeedRisk(),i.getStatus(),i.getCreatedBy().getId(),i.getCreatedAt(),i.getUpdatedAt());}
 private RiskView view(RiskAnalysis r){return new RiskView(r.getId(),r.getIncident().getId(),r.getScore(),r.getSeverity(),parse(r.getNodeProbabilities()),parse(r.getLocalFactors()),r.getAnalyzedAt());}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@Valid @RequestBody LoginRequest req){AppUser u=users.findByEmailIgnoreCase(req.email()).orElse(null);if(u==null||!u.isEnabled()||!encoder.matches(req.password(),u.getPasswordHash()))return ResponseEntity.status(401).body(Map.of("status",401,"error","Unauthorized","message","Invalid email or password"));return ResponseEntity.ok(new LoginResponse(jwt.issue(u),"Bearer",28800,new UserView(u.getId(),u.getEmail(),u.getName(),u.getRole().name(),u.isEnabled(),u.getCreatedAt())));}
 @GetMapping("/auth/me") public UserView me(Authentication a){AppUser u=actor(a);return new UserView(u.getId(),u.getEmail(),u.getName(),u.getRole().name(),u.isEnabled(),u.getCreatedAt());}
 @GetMapping("/users") @PreAuthorize("hasRole('ADMIN')") public Page<UserView> users(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return users.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("id").descending())).map(u->new UserView(u.getId(),u.getEmail(),u.getName(),u.getRole().name(),u.isEnabled(),u.getCreatedAt()));}
 @GetMapping("/incidents") public Page<IncidentView> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String q,@RequestParam(required=false)String status){Specification<Incident> spec=(root,query,cb)->cb.conjunction();if(q!=null&&!q.isBlank())spec=spec.and((root,query,cb)->cb.or(cb.like(cb.lower(root.get("title")),"%"+q.toLowerCase()+"%"),cb.like(cb.lower(root.get("location")),"%"+q.toLowerCase()+"%")));if(status!=null)spec=spec.and((root,query,cb)->cb.equal(root.get("status"),status.toUpperCase()));return incidents.findAll(spec,PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending())).map(this::view);}
 @PostMapping("/incidents") @PreAuthorize("hasAnyRole('ADMIN','ANALYST','RESPONDER')") public ResponseEntity<IncidentView> create(@Valid @RequestBody IncidentRequest req,Authentication a){AppUser u=actor(a);Incident i=incidents.save(new Incident(req.title(),req.type(),req.location(),req.description(),req.seedRisk(),u));audit.save(new AuditLog(u,"CREATE","INCIDENT",i.getId().toString(),i.getTitle()));return ResponseEntity.status(201).body(view(i));}
 @GetMapping("/incidents/{id}") public IncidentView get(@PathVariable long id){return view(incident(id));}
 @PutMapping("/incidents/{id}") @PreAuthorize("hasAnyRole('ADMIN','ANALYST','RESPONDER')") public IncidentView update(@PathVariable long id,@Valid @RequestBody IncidentRequest req,Authentication a){AppUser u=actor(a);Incident i=incident(id);i.update(req.title(),req.type(),req.location(),req.description(),req.seedRisk());audit.save(new AuditLog(u,"UPDATE","INCIDENT",id+"",req.title()));return view(i);}
 @PatchMapping("/incidents/{id}/status") @PreAuthorize("hasAnyRole('ADMIN','ANALYST','RESPONDER')") public IncidentView status(@PathVariable long id,@Valid @RequestBody StatusRequest req,Authentication a){AppUser u=actor(a);Incident i=incident(id);i.setStatus(req.status());audit.save(new AuditLog(u,"STATUS","INCIDENT",id+"",req.status()));return view(i);}
 @GetMapping("/risks") public Page<RiskView> riskList(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return risks.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("analyzedAt").descending())).map(this::view);}
 @GetMapping("/risks/{id}") public RiskView risk(@PathVariable long id){Incident i=incident(id);return risks.findTopByIncidentOrderByAnalyzedAtDesc(i).map(this::view).orElseThrow(()->new IllegalArgumentException("No risk analysis for incident: "+id));}
 @PostMapping("/risks/analyze/{id}") @PreAuthorize("hasAnyRole('ADMIN','ANALYST','RESPONDER')") public RiskView analyze(@PathVariable long id,@RequestBody(required=false)Map<String,Double> factors,Authentication a){AppUser u=actor(a);Incident i=incident(id);Map<String,Double> f=factors==null?Map.of():factors;var x=engine.analyze(i.getSeedRisk(),f);RiskAnalysis r=risks.save(new RiskAnalysis(i,x.score(),x.severity(),stringify(x.nodes()),stringify(f),u));if(!x.severity().equals("LOW"))alerts.save(new Alert(i,x.severity(),"Cascade risk analyzed at "+x.score()));audit.save(new AuditLog(u,"ANALYZE","RISK",id+"",x.severity()+" score="+x.score()));return view(r);}
 @GetMapping("/alerts") public Page<AlertView> alertList(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return alerts.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending())).map(x->new AlertView(x.getId(),x.getIncident().getId(),x.getSeverity(),x.getMessage(),x.getStatus(),x.getCreatedAt()));}
 @PatchMapping("/alerts/{id}/status") @PreAuthorize("hasAnyRole('ADMIN','ANALYST','RESPONDER')") public AlertView alertStatus(@PathVariable long id,@Valid @RequestBody AlertStatusRequest req,Authentication a){Alert x=alerts.findById(id).orElseThrow(()->new IllegalArgumentException("Alert not found: "+id));x.setStatus(req.status());audit.save(new AuditLog(actor(a),"STATUS","ALERT",id+"",req.status()));return new AlertView(x.getId(),x.getIncident().getId(),x.getSeverity(),x.getMessage(),x.getStatus(),x.getCreatedAt());}
 @GetMapping("/recommendations") public Page<RecommendationView> recs(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return recommendations.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending())).map(x->new RecommendationView(x.getId(),x.getIncident().getId(),x.getText(),x.getStatus(),x.getCreatedAt()));}
 @PostMapping("/simulations") @PreAuthorize("hasAnyRole('ADMIN','ANALYST','RESPONDER')") public ResponseEntity<SimulationView> simulate(@Valid @RequestBody SimulationRequest req,Authentication a){AppUser u=actor(a);Incident i=incident(req.incidentId());double seed=req.seed()==null?i.getSeedRisk():req.seed();Map<String,Double> f=req.localFactors()==null?Map.of():req.localFactors();var x=engine.analyze(seed,f);Simulation s=simulations.save(new Simulation(i,u,stringify(Map.of("seed",seed,"localFactors",f)),x.score(),x.severity(),stringify(x.nodes())));audit.save(new AuditLog(u,"SIMULATE","SIMULATION",s.getId()+"","incident="+i.getId()));return ResponseEntity.status(201).body(simView(s));}
 private SimulationView simView(Simulation s){Map<String,Object> inputs=parseObject(s.getInputs());return new SimulationView(s.getId(),s.getIncident().getId(),s.getScore(),s.getSeverity(),parse(s.getNodeProbabilities()),parseFactors(inputs.get("localFactors")),s.getCreatedAt());}
 @GetMapping("/simulations") public Page<SimulationView> simList(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return simulations.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending())).map(this::simView);}
 @GetMapping("/simulations/{id}") public SimulationView sim(@PathVariable long id){return simView(simulations.findById(id).orElseThrow(()->new IllegalArgumentException("Simulation not found: "+id)));}
 @GetMapping("/dashboard/summary") public Summary summary(){
  Specification<Incident> openIncidents=(root,query,cb)->cb.equal(root.get("status"),"OPEN");
  Specification<Alert> activeAlerts=(root,query,cb)->cb.equal(root.get("status"),"ACTIVE");
  long total=incidents.count(),open=incidents.count(openIncidents),active=alerts.count(activeAlerts);
  return new Summary(total,open,active,simulations.count());
 }
 @GetMapping("/reports/summary") public Map<String,Object> report(){return Map.of("generatedAt",java.time.Instant.now(),"summary",summary(),"riskAnalyses",risks.count(),"recommendations",recommendations.count());}
}
